from pathlib import Path
R=Path(__file__).resolve().parents[1]/'design'
css='''*{box-sizing:border-box}body{margin:0;background:#e9eee6;color:#203e34;font:15px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}header{padding:20px 30px;background:#fff;display:flex;align-items:center;gap:25px;border-bottom:1px solid #d7dfd4}header h2{margin:0}a{color:#255d48}.workspace{display:grid;grid-template-columns:280px 1fr;min-height:calc(100vh - 90px)}aside{padding:20px;height:calc(100vh - 90px);overflow:auto;background:#f4f6f0}button{font:inherit;border:0;cursor:pointer;color:inherit;background:transparent;text-align:left}aside button{display:block;width:100%;padding:10px;border-radius:9px}.current{background:#dcebd6;color:#255d48}main{padding:25px;display:grid;justify-items:center;align-content:start;gap:12px}.phone{width:390px;border:7px solid #203e34;border-radius:35px;overflow:hidden;box-shadow:0 20px 70px #203e3422;background:#f7f8f2}.viewport{height:830px;overflow:auto;position:relative}.status{padding:12px 22px;font-size:12px;display:flex;justify-content:space-between}.appbar{padding:8px 18px;display:flex;justify-content:space-between;color:#255d48}.content{padding:10px 20px 25px}h1{font-size:26px;line-height:1.35;margin:12px 0 22px;font-weight:650}.eyebrow,.muted{font-size:12px;color:#67796e}.card{display:block;width:100%;padding:16px;background:white;border-radius:17px;margin:12px 0;white-space:pre-line;border:1px solid transparent}.card strong{display:block;font-size:16px}.card span{display:block;font-size:13px;color:inherit;opacity:.85;margin-top:6px}.hero{background:#255d48;color:white}.hero strong{font-size:25px}.tint{background:#e8f1e4}.search{background:white;border:1px solid #cdd9c8}.sentence{line-height:1.8}.actions{margin-top:24px}.primary{display:block;width:100%;padding:14px 12px;text-align:center;background:#255d48;color:white;border-radius:12px;margin:10px 0}.secondary{display:flex;gap:10px;flex-wrap:wrap}.secondary button{padding:8px;font-size:12px;color:#527563}nav{display:flex;position:sticky;bottom:0;padding:12px 5px;background:#fffefa;border-top:1px solid #e1e6dc}nav button{flex:1;text-align:center;font-size:12px;color:#819083}nav .active{font-weight:650;color:#255d48}input:not([type=checkbox]):not([type=radio]),textarea,select{display:block;width:100%;padding:12px;margin:9px 0;border:1px solid #c9d6c3;border-radius:10px;background:white;font:inherit;color:inherit}label{display:block;margin-top:12px}input[type=checkbox]{float:right}.calendar,.answergrid{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}.calendar button,.answergrid button{background:white;text-align:center;border-radius:7px;padding:7px}.calendar small{display:block}.selected{background:#e8f1e4!important;border:1px solid #255d48!important}.inline{color:#255d48;border-bottom:1px solid #255d48;font-weight:700}footer{max-width:650px;color:#67796e;font-size:12px}.label{font-size:13px;color:#52694f}#reset{margin-left:auto;border:1px solid #c9d6c3;border-radius:10px;padding:8px 12px}@media(max-width:750px){.workspace{display:block}aside{height:120px;white-space:nowrap;overflow:auto}aside button{display:inline-block;width:auto}main{padding:12px}.phone{max-width:100%}header{padding:12px;flex-wrap:wrap}}'''
body='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>词伴0.1 · 离线交互原型</title><style>'''+css+'''</style><header><h2>词伴 / 0.1</h2><a href="index.html">设计总览</a><a href="../index.html">交付包</a><button id="reset">重置演示</button></header><div class="workspace"><aside aria-label="页面目录"></aside><main><div class="label" id="label"></div><div class="phone"><div class="viewport" id="viewport"><div id="screen"></div></div></div><footer>离线评审原型：所有名字、进度及成绩均为演示数据。可试批量录词、标注、点词查询和答题计分；不连接微信、AI或后端，不上传任何数据。页面切换为设计演示，并非真实业务状态校验。</footer></main></div><script id="screen-data" type="application/json">'''+(R/'screens.json').read_text().replace('</','<\/')+'''</script><script>'''+(R/'prototype.js').read_text()+'''</script></html>'''
(R/'prototype.html').write_text(body)
